}

function ValidatedInput({ name, label, error, onBlur, onChange, value }) {
  return (
    <div className="form-group">
      <label htmlFor={name}>{label}</label>
      <input
        id={name}
        name={name}
        value={value}
        onChange={onChange}
        onBlur={onBlur}
        className={error ? 'input-error' : ''}
        aria-invalid={!!error}
      />
      {error && <span className="error-message" role="alert">{error}</span>}
    </div>
  );
}
